-- Seed 1 tháng vận hành (2026-04-15 -> 2026-05-15)
-- Chạy: mysql -u root -p hotel_management < hotel_management_seed_1month.sql
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
USE `hotel_management`;

DELETE FROM `service_usage`;
DELETE FROM `invoices`;
DELETE FROM `bookings`;

ON DUPLICATE KEY UPDATE `full_name`=VALUES(`full_name`), `phone`=VALUES(`phone`);




UPDATE `rooms` SET `status`='AVAILABLE' WHERE `status`!='MAINTENANCE';
UPDATE `rooms` SET `status`='OCCUPIED' WHERE `id`=3;
UPDATE `rooms` SET `status`='OCCUPIED' WHERE `id`=4;
SET FOREIGN_KEY_CHECKS = 1;
-- Bookings: 40, Invoices: 28, Service usage: 33